@app.route("/")
def index() -> Any:
    return PAGE


@app.route("/api/user/<int:uid>")
def get_user(uid: int) -> Any:
    user = _USERS.get(uid)
    if not user:
        return jsonify({"error": "User not found"}), 404
    return jsonify(user)


@app.route("/api/users")
def list_users() -> Any:
    return jsonify({"users": [{"id": u["id"], "username": u["username"]} for u in _USERS.values()]})


